//! Standards P32: versioned ontology, unit, coordinate, and semantic-loss integrity.
use bioprism_foundation::{PRECLINICAL_BOUNDARY,RESEARCH_CONTRACT_SCHEMA_VERSION};
use bioprism_ids::ContentHash;
use serde::{Deserialize,Serialize};
use serde_json::{json,Value};
use std::collections::BTreeSet;
use thiserror::Error;
pub const BOUNDARY:&str=PRECLINICAL_BOUNDARY;
pub const CONTENT_TYPE:&str="application/vnd.aurora.standards.migration-integrity-card-1+json";
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct StandardObject4{pub object_id:String,pub standard:String,pub version:String,pub semantic_loss:String,pub coordinate_frame:String,pub unit:String,pub evidence_state:String,pub digest:String,pub local:bool,pub aggregate_only:bool}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct MigrationIntegrityRequest4{pub schema_version:String,pub request_id:String,pub purpose:String,pub objects:Vec<StandardObject4>,pub required_object_order:Vec<String>,pub required_standard_order:Vec<String>,pub replay_identity:String,pub policy_allowed:bool,pub protected_closure:bool,pub signed_manifest:bool,pub raw_data_local:bool,pub aggregate_only:bool,pub adversarial_events:Vec<String>,pub object_budget:usize,pub boundary:String}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct MigrationIntegrityArtifact4{pub artifact_id:String,pub content_type:String,pub content_hash:String,pub semantic_loss:Vec<String>,pub evidence_digests:Vec<String>,pub boundary:String}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct MigrationIntegrityCard7{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub request_id:String,pub purpose:String,pub disposition:String,pub object_order:Vec<String>,pub accepted_order:Vec<String>,pub rejected_order:Vec<String>,pub unknown_order:Vec<String>,pub omitted_order:Vec<String>,pub standard_order:Vec<String>,pub version_order:Vec<String>,pub coordinate_order:Vec<String>,pub unit_order:Vec<String>,pub loss_order:Vec<String>,pub replay_identity:String,pub closure_digest:String,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String,pub effect_receipts:Vec<String>,pub artifact:MigrationIntegrityArtifact4}
#[derive(Debug,Error)] pub enum MigrationIntegrityError{#[error("migration integrity input is invalid: {0}")] Invalid(String),#[error("migration integrity digest failed: {0}")] Digest(String)}
fn digest(v:&str)->bool{v.len()==64&&v.bytes().all(|b|b.is_ascii_hexdigit())}fn canonical(v:&[String])->bool{v.windows(2).all(|w|w[0]<w[1])}fn invalid(v:impl Into<String>)->MigrationIntegrityError{MigrationIntegrityError::Invalid(v.into())}
pub fn manifest(feature_id:&str,contract_version:&str,scale:&str,mode:&str)->Value{json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"capability_id":feature_id,"version":contract_version,"owner_crate":"standards","consumers":["harmonization compiler","ontology steward","analysis runtime","research workbench"],"behavior":format!("qualify versioned standard migrations at {scale} ({mode})"),"value":"prevents coordinate, unit, ontology, and semantic-loss incompatibilities from entering reproducible research workflows","input_schema":"MigrationIntegrityRequest4@1","output_schema":"MigrationIntegrityCard7@1","effects":["emit:migration-card","retain:semantic-loss","block:unsafe-migration"],"permissions":["read:local-standard-fixtures"],"determinism":"byte_stable","autonomy_tier":"A1","boundary":BOUNDARY})}
fn validate_card(c:&MigrationIntegrityCard7)->Result<(),MigrationIntegrityError>{if c.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||c.feature_id.is_empty()||c.request_id.is_empty()||c.purpose.is_empty()||c.boundary!=BOUNDARY||c.artifact.boundary!=BOUNDARY||!c.raw_data_local||!c.aggregate_only||!digest(&c.replay_identity)||!digest(&c.closure_digest)||c.artifact.content_type!=CONTENT_TYPE||c.artifact.content_hash!=c.closure_digest{return Err(invalid("migration identity, locality, artifact, digest, or boundary is incomplete"));}for v in [&c.object_order,&c.accepted_order,&c.rejected_order,&c.unknown_order,&c.omitted_order,&c.standard_order,&c.version_order,&c.coordinate_order,&c.unit_order,&c.loss_order,&c.effect_receipts]{if !canonical(v){return Err(invalid("migration vectors are not canonical"));}}let ids=c.object_order.iter().collect::<BTreeSet<_>>();let states=c.accepted_order.iter().chain(&c.rejected_order).chain(&c.unknown_order).chain(&c.omitted_order).collect::<Vec<_>>();if states.len()!=ids.len()||states.into_iter().collect::<BTreeSet<_>>()!=ids{return Err(invalid("object states do not partition objects"));}Ok(())}
pub fn qualify(q:&MigrationIntegrityRequest4,feature_id:&str,contract_version:&str,scale:&str,mode:&str)->Result<MigrationIntegrityCard7,MigrationIntegrityError>{if q.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||q.request_id.trim().is_empty()||q.purpose.trim().is_empty()||q.objects.is_empty()||q.required_object_order.is_empty()||!canonical(&q.required_object_order)||!canonical(&q.required_standard_order)||!digest(&q.replay_identity)||q.boundary!=BOUNDARY||!q.raw_data_local||!q.aggregate_only||!canonical(&q.adversarial_events)||q.object_budget==0{return Err(invalid("migration identity, ordering, digest, locality, boundary, or budget is invalid"));}let mut rows=q.objects.clone();rows.sort_by(|a,b|a.object_id.cmp(&b.object_id));let mut seen=BTreeSet::new();let mut accepted=BTreeSet::new();let mut rejected=BTreeSet::new();let mut unknown=BTreeSet::new();let mut omitted=BTreeSet::new();let mut standards=BTreeSet::new();let mut versions=BTreeSet::new();let mut coordinates=BTreeSet::new();let mut units=BTreeSet::new();let mut losses=BTreeSet::new();let mut evidence=BTreeSet::new();for o in &rows{if o.object_id.trim().is_empty()||!seen.insert(o.object_id.clone())||o.standard.trim().is_empty()||o.version.trim().is_empty()||o.semantic_loss.trim().is_empty()||o.coordinate_frame.trim().is_empty()||o.unit.trim().is_empty()||o.evidence_state.trim().is_empty()||!digest(&o.digest)||!o.local||!o.aggregate_only{return Err(invalid("object identity, standard, version, loss, coordinate, unit, evidence, or locality is invalid"));}standards.insert(format!("{}:{}",o.object_id,o.standard));versions.insert(format!("{}:{}",o.object_id,o.version));coordinates.insert(format!("{}:{}",o.object_id,o.coordinate_frame));units.insert(format!("{}:{}",o.object_id,o.unit));losses.insert(format!("{}:{}",o.object_id,o.semantic_loss));evidence.insert(o.digest.clone());if o.evidence_state=="unknown"||o.digest==q.replay_identity{unknown.insert(o.object_id.clone());}else if o.semantic_loss!="none"||o.standard=="unknown"{rejected.insert(o.object_id.clone());}else if !q.required_object_order.contains(&o.object_id){omitted.insert(o.object_id.clone());}else{accepted.insert(o.object_id.clone());}}let missing=q.required_object_order.iter().filter(|x|!seen.contains(*x)).cloned().collect::<Vec<_>>();let global=!q.policy_allowed||!q.protected_closure||!q.signed_manifest||!q.raw_data_local||!q.aggregate_only||!q.adversarial_events.is_empty()||rows.len()>q.object_budget;if global{omitted.extend(seen.iter().cloned());accepted.clear();rejected.clear();unknown.clear();}let disposition=if global{"blocked"}else if !missing.is_empty()||!unknown.is_empty(){"unknown"}else if !rejected.is_empty()||!omitted.is_empty(){"partial"}else{"qualified"};let object_order=seen.iter().cloned().collect::<Vec<_>>();let accepted_order=accepted.into_iter().collect::<Vec<_>>();let rejected_order=rejected.into_iter().collect::<Vec<_>>();let unknown_order=unknown.into_iter().collect::<Vec<_>>();let omitted_order=omitted.into_iter().collect::<Vec<_>>();let body=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":contract_version,"feature_id":feature_id,"request_id":q.request_id,"purpose":q.purpose,"disposition":disposition,"object_order":object_order,"accepted_order":accepted_order,"rejected_order":rejected_order,"unknown_order":unknown_order,"omitted_order":omitted_order,"standard_order":standards.into_iter().collect::<Vec<_>>(),"version_order":versions.into_iter().collect::<Vec<_>>(),"coordinate_order":coordinates.into_iter().collect::<Vec<_>>(),"unit_order":units.into_iter().collect::<Vec<_>>(),"loss_order":losses.into_iter().collect::<Vec<_>>(),"replay_identity":q.replay_identity,"raw_data_local":true,"aggregate_only":true,"boundary":BOUNDARY});let closure_digest=ContentHash::of_value(&body).map_err(|e|MigrationIntegrityError::Digest(e.to_string()))?.to_string();let effect_receipts=if disposition=="qualified"{vec![format!("approve:migration:{}",q.request_id)]}else{vec!["block:unsafe-migration".into()]};let artifact=MigrationIntegrityArtifact4{artifact_id:format!("standards-migration:{}",q.request_id),content_type:CONTENT_TYPE.into(),content_hash:closure_digest.clone(),semantic_loss:body["omitted_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),evidence_digests:evidence.into_iter().collect(),boundary:BOUNDARY.into()};let c=MigrationIntegrityCard7{schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(),contract_version:contract_version.into(),feature_id:feature_id.into(),request_id:q.request_id.clone(),purpose:q.purpose.clone(),disposition:disposition.into(),object_order:body["object_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),accepted_order,rejected_order,unknown_order,omitted_order,standard_order:body["standard_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),version_order:body["version_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),coordinate_order:body["coordinate_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),unit_order:body["unit_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),loss_order:body["loss_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),replay_identity:q.replay_identity.clone(),closure_digest,raw_data_local:true,aggregate_only:true,boundary:BOUNDARY.into(),effect_receipts,artifact};let _=(scale,mode);validate_card(&c)?;Ok(c)}
